require 'config/koneksi.php'; require 'includes/functions.php'; $page_title='Cek Status'; $data=null;$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$no=trim($_POST['no_pendaftaran']??'');$hp=preg_replace('/\\s+/','',trim($_POST['no_whatsapp']??''));$st=$conn->prepare("SELECT no_pendaftaran,nama_lengkap,pilihan_kelas,status,catatan_admin,created_at FROM pendaftar WHERE no_pendaftaran=? AND REPLACE(no_whatsapp,' ','')=? LIMIT 1");$st->bind_param('ss',$no,$hp);$st->execute();$data=$st->get_result()->fetch_assoc();if(!$data)$error='Data tidak ditemukan. Periksa kembali nomor pendaftaran dan nomor WhatsApp.';}
include 'includes/header.php';?>
<main class="page"><div class="container" style="max-width:760px"><div class="page-heading"><div class="kicker">INFORMASI PENDAFTARAN</div><h1>Cek status pendaftaran</h1><p>Masukkan nomor pendaftaran dan nomor WhatsApp orang tua/wali.</p></div><div class="panel"><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="field"><label>Nomor pendaftaran</label><input name="no_pendaftaran" required placeholder="Contoh: PPDB-2611-ABC123"></div><div class="field"><label>Nomor WhatsApp orang tua/wali</label><input name="no_whatsapp" required placeholder="Nomor yang digunakan saat mendaftar"></div><button class="btn btn-primary">Periksa Status ↗</button></form><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><?php if($data):?><div class="status-result"><span class="status <?=badge_class($data['status'])?>"><?=e($data['status'])?></span><h2><?=e($data['nama_lengkap'])?></h2><p><?=e($data['no_pendaftaran'])?> · <?=e($data['pilihan_kelas'])?></p><?php if($data['catatan_admin']):?><div class="notice"><?=e($data['catatan_admin'])?></div><?php endif;?><p>Terdaftar pada <?=e(date('d-m-Y',strtotime($data['created_at'])))?>. Untuk informasi lebih lanjut, hubungi pihak sekolah.</p></div><?php endif;?></div></div></main><?php include 'includes/footer.php';?>
